<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { Head } from '@inertiajs/vue3';
import ErpLayout from '@/layouts/ErpLayout.vue';
import Icon from '@/components/dashboard/Icon.vue';

const props=withDefaults(defineProps<{canManage?:boolean}>(),{canManage:false});
type Rate={id?:number;zone_code:string;min_weight_grams:number;max_weight_grams:number|null;base_charge:number;additional_per_kg:number;cod_charge_percent:number;is_enabled:boolean};
type Provider={id:number;code:string;name:string;description:string|null;logo_url:string|null;is_enabled:boolean;priority:number;environment:string;capabilities:string[];service_zones:string[];has_credentials:boolean;health_status:string;rates:Rate[]};
const providers=ref<Provider[]>([]),loading=ref(false),saving=ref(false),error=ref(''),success=ref('');
const zones=[{value:'inside_dhaka',label:'Inside Dhaka'},{value:'outside_dhaka',label:'Outside Dhaka'},{value:'remote_special',label:'Remote / Special'}];
const blank=()=>({id:0,code:'steadfast',name:'',description:'',logo_url:'',is_enabled:false,priority:10,environment:'sandbox',capabilities:['booking','tracking','cod'],service_zones:zones.map(z=>z.value),credentials:{},rates:[{zone_code:'inside_dhaka',min_weight_grams:0,max_weight_grams:500,base_charge:60,additional_per_kg:20,cod_charge_percent:0,is_enabled:true},{zone_code:'outside_dhaka',min_weight_grams:0,max_weight_grams:500,base_charge:100,additional_per_kg:25,cod_charge_percent:0,is_enabled:true},{zone_code:'remote_special',min_weight_grams:0,max_weight_grams:500,base_charge:130,additional_per_kg:30,cod_charge_percent:0,is_enabled:true}] as Rate[]});
const form=reactive<any>(blank()),editing=ref(false),modal=ref(false);
const csrf=()=>decodeURIComponent(document.cookie.split('; ').find(v=>v.startsWith('XSRF-TOKEN='))?.split('=').slice(1).join('=')??'');
async function api(url:string,method='GET',body?:unknown){const r=await fetch(url,{method,credentials:'same-origin',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest',...(body?{'Content-Type':'application/json','X-XSRF-TOKEN':csrf()}:{})},body:body?JSON.stringify(body):undefined});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.message||Object.values(j.errors??{}).flat().join(' ')||`Request failed (${r.status})`);return j;}
async function load(){loading.value=true;error.value='';try{const r=await api('/api/v1/backend/shipping/courier-providers');providers.value=r.data;}catch(e:any){error.value=e.message;}finally{loading.value=false;}}
function create(){Object.assign(form,blank());editing.value=false;modal.value=true;}
function edit(p:Provider){Object.assign(form,{...blank(),...JSON.parse(JSON.stringify(p)),credentials:{}});editing.value=true;modal.value=true;}
async function save(){saving.value=true;error.value='';success.value='';try{const payload={...form,credentials:form.credentials&&Object.keys(form.credentials).length?form.credentials:undefined};await api(editing.value?`/api/v1/backend/shipping/courier-providers/${form.id}`:'/api/v1/backend/shipping/courier-providers',editing.value?'PUT':'POST',payload);modal.value=false;success.value='Courier provider settings saved.';await load();}catch(e:any){error.value=e.message;}finally{saving.value=false;}}
async function toggle(p:Provider){try{await api(`/api/v1/backend/shipping/courier-providers/${p.id}`,'PUT',{is_enabled:!p.is_enabled});await load();}catch(e:any){error.value=e.message;}}
function addRate(){form.rates.push({zone_code:'inside_dhaka',min_weight_grams:0,max_weight_grams:1000,base_charge:0,additional_per_kg:0,cod_charge_percent:0,is_enabled:true});}
function removeRate(i:number){form.rates.splice(i,1);}
onMounted(load);
</script>
<template>
<Head title="Courier Providers"/><ErpLayout>
<div class="space-y-6 p-4 md:p-6">
 <div class="flex flex-wrap items-center justify-between gap-3"><div><h1 class="text-2xl font-semibold text-slate-900 dark:text-white">Courier Providers</h1><p class="mt-1 text-sm text-slate-500">Manage delivery partners, capabilities, service zones and demo/admin rate rules.</p></div><button v-if="props.canManage" @click="create" class="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-semibold text-white hover:bg-indigo-700">Add provider</button></div>
 <div v-if="error" class="rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700">{{error}}</div><div v-if="success" class="rounded-lg border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-700">{{success}}</div>
 <div v-if="loading" class="py-12 text-center text-slate-500">Loading courier providers…</div>
 <div v-else class="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
  <article v-for="p in providers" :key="p.id" class="rounded-xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-700 dark:bg-slate-900">
   <div class="flex items-start justify-between gap-3"><div><h2 class="font-semibold text-slate-900 dark:text-white">{{p.name}}</h2><p class="mt-1 text-xs uppercase tracking-wide text-slate-400">{{p.code}} · Priority {{p.priority}}</p></div><span :class="p.is_enabled?'bg-emerald-100 text-emerald-700':'bg-slate-100 text-slate-500'" class="rounded-full px-2.5 py-1 text-xs font-medium">{{p.is_enabled?'Active':'Inactive'}}</span></div>
   <p class="mt-3 text-sm text-slate-500">{{p.description||'No description added.'}}</p>
   <div class="mt-4 flex flex-wrap gap-1.5"><span v-for="c in p.capabilities" :key="c" class="rounded bg-indigo-50 px-2 py-1 text-xs text-indigo-700">{{c}}</span></div>
   <div class="mt-4 flex items-center justify-between border-t border-slate-100 pt-3 text-xs text-slate-500 dark:border-slate-800"><span>{{p.rates.length}} rate rules · {{p.environment}}</span><span>{{p.health_status}}</span></div>
   <div v-if="props.canManage" class="mt-4 flex gap-2"><button @click="edit(p)" class="flex-1 rounded-lg border px-3 py-2 text-sm hover:bg-slate-50 dark:border-slate-700 dark:hover:bg-slate-800">Configure</button><button @click="toggle(p)" class="rounded-lg px-3 py-2 text-sm" :class="p.is_enabled?'bg-amber-50 text-amber-700':'bg-emerald-50 text-emerald-700'">{{p.is_enabled?'Disable':'Enable'}}</button></div>
  </article>
 </div>
 <div class="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900"><strong>Integration safety:</strong> Enabling a provider only makes it available in configuration. It does not prove that API credentials, serviceability, live quotes or booking are operational. Verify each provider in sandbox before production use. Rates entered here are administrative rates, not verified live quotes.</div>
</div>
<div v-if="modal" class="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-slate-950/50 p-4"><div class="my-6 w-full max-w-3xl rounded-2xl bg-white p-5 shadow-xl dark:bg-slate-900">
 <div class="mb-5 flex items-center justify-between"><h2 class="text-lg font-semibold">{{editing?'Configure':'Add'}} courier provider</h2><button @click="modal=false" class="text-slate-500">✕</button></div>
 <div class="grid gap-3 md:grid-cols-2"><label class="text-sm">Provider code<select v-model="form.code" :disabled="editing" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"><option v-for="c in ['steadfast','carrybee','bangladesh_post','pathao','redx']" :key="c" :value="c">{{c}}</option></select></label><label class="text-sm">Display name<input v-model="form.name" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"/></label><label class="text-sm">Priority<input v-model.number="form.priority" type="number" min="1" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"/></label><label class="text-sm">Environment<select v-model="form.environment" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"><option value="sandbox">Sandbox</option><option value="production">Production</option></select></label><label class="text-sm md:col-span-2">Description<input v-model="form.description" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"/></label><label class="text-sm md:col-span-2">Logo URL<input v-model="form.logo_url" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"/></label></div>
 <div class="mt-4 flex flex-wrap gap-4 text-sm"><label><input v-model="form.is_enabled" type="checkbox" class="mr-2"/>Active</label><label v-for="c in ['quote','booking','tracking','cod','webhook']" :key="c"><input v-model="form.capabilities" type="checkbox" :value="c" class="mr-1"/>{{c}}</label></div>
 <div class="mt-4"><h3 class="mb-2 font-semibold">API credentials (encrypted at rest)</h3><p class="mb-2 text-xs text-slate-500">Leave blank to retain existing credentials. Never enter credentials in storefront code.</p><div class="grid gap-2 md:grid-cols-2"><label v-for="key in ['api_key','secret_key','access_token','store_id','base_url','api_token']" :key="key" class="text-sm">{{key}}<input v-model="form.credentials[key]" :type="key.includes('key')||key.includes('token')?'password':'text'" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"/></label></div></div>
 <div class="mt-5"><div class="mb-2 flex items-center justify-between"><h3 class="font-semibold">Weight-based rate rules</h3><button @click="addRate" class="text-sm font-medium text-indigo-600">+ Add rate</button></div><div v-for="(r,i) in form.rates" :key="i" class="mb-3 grid gap-2 rounded-lg border p-3 md:grid-cols-4"><select v-model="r.zone_code" class="rounded border p-2 text-sm dark:bg-slate-800"><option v-for="z in zones" :key="z.value" :value="z.value">{{z.label}}</option></select><input v-model.number="r.min_weight_grams" type="number" min="0" placeholder="Min grams" class="rounded border p-2 text-sm"/><input v-model.number="r.max_weight_grams" type="number" min="1" placeholder="Max grams (blank = no max)" class="rounded border p-2 text-sm"/><input v-model.number="r.base_charge" type="number" min="0" placeholder="Base charge ৳" class="rounded border p-2 text-sm"/><input v-model.number="r.additional_per_kg" type="number" min="0" placeholder="Additional / kg" class="rounded border p-2 text-sm"/><input v-model.number="r.cod_charge_percent" type="number" min="0" max="100" step="0.001" placeholder="COD %" class="rounded border p-2 text-sm"/><label class="flex items-center text-sm"><input v-model="r.is_enabled" type="checkbox" class="mr-2"/>Enabled</label><button @click="removeRate(Number(i))" class="text-left text-sm text-red-600">Remove rate</button></div></div>
 <div class="mt-6 flex justify-end gap-2"><button @click="modal=false" class="rounded-lg border px-4 py-2 text-sm">Cancel</button><button @click="save" :disabled="saving" class="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-semibold text-white disabled:opacity-50">{{saving?'Saving…':'Save provider'}}</button></div>
</div></div>
</ErpLayout>
</template>
